// === Tab: mySketch ===
// For the #WCCChallenge «Upside Down» (join the discord! https://discord.gg/S8c7qcjw2b)
//
// I did an upside down pyramid, more an excuse to play with shaders
// Tried to do something interesting with the `baseStrokeShader` for the glitchy effect, not what I wanted at all
// but got to learn more of how these base shaders work

let layers = []
let currentLayer = 1
let maxLayers = 40
let layerHeight = 1.3
let fallSpeed = 30
let unitSize = 20
let spawnMargin = 3

function calculateMaxLayers() {
  let minLayers = 10
  let maxLayersLimit = 40
  let layerPixelHeight = layerHeight * unitSize
  let topMargin = 100
  let availableHeight = height - topMargin
  let calculatedLayers = floor(availableHeight / layerPixelHeight)
  return constrain(calculatedLayers, minLayers, maxLayersLimit)
}

function generateGrayscalePalette() {
  let palette = []
  for (let i = 0; i < 8; i++) {
    let grayValue = floor((i / 7) * 255)
    let hex = '#' + grayValue.toString(16).padStart(2, '0').repeat(3)
    palette.push(hex)
  }
  return palette
}

var palette
let spawnStartY = 0
let globalRotationSpeed = 0.008
let squigglyShader = null

function calculateSpawnPosition() {
  let bottomY = height / 4
  let totalPyramidHeight = maxLayers * layerHeight * unitSize
  let marginHeight = spawnMargin * layerHeight * unitSize
  spawnStartY = bottomY - totalPyramidHeight - marginHeight
}

let frag = `
precision mediump float;

uniform vec2 resolution;
uniform vec3 uColor;
uniform float blockSize;
uniform sampler2D tex0;

const float Threshold = 0.9;
const float Multiplicator = 1.0 / 17.0;
const mat4 DitherMatrix = (mat4(
    1, 13, 4, 16,
    9, 5, 12, 8,
    3, 15, 2, 14,
    11, 7, 10, 6
    ) - 8.) * Multiplicator;

float GetLuminance(vec4 c) {
  return (0.2126*c.r + 0.7152*c.g + 0.0722*c.b);
}

float AdjustDither( float val, vec2 coord ) {
    vec2 coordMod = mod(coord, 4.0);
    int xMod = int(coordMod.x);
    int yMod = int(coordMod.y);

    vec4 col;
    if (xMod == 0) col = DitherMatrix[0];
    else if (xMod == 1) col = DitherMatrix[1];
    else if (xMod == 2) col = DitherMatrix[2];
    else if (xMod == 3) col = DitherMatrix[3];

    float adjustment = 0.;
    if (yMod == 0) adjustment = col.x;
    else if (yMod == 1) adjustment = col.y;
    else if (yMod == 2) adjustment = col.z;
    else if (yMod == 3) adjustment = col.w;

    return val + (val * adjustment);
}

void main (void) {
  vec2 quantizedCoord = floor(gl_FragCoord.xy / blockSize) * blockSize;
  vec2 uv = quantizedCoord / resolution;

  vec4 c = texture2D(tex0, uv);

  float luminance = GetLuminance(c);

  if (AdjustDither(luminance, quantizedCoord)>Threshold) {
    gl_FragColor = vec4(1., 1., 1., 1.);
  } else {
    gl_FragColor = vec4(uColor, 1.);
  }
}`

let ditherShader

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL)
  palette = generateGrayscalePalette()
  pixelDensity(1)

  ortho(-width / 2, width / 2, -height / 2, height / 2, -2000, 2000)
  maxLayers = calculateMaxLayers()
  createSquigglyShader()
  calculateSpawnPosition()
  ditherShader = createFilterShader(frag)
}

function draw() {
  clear()
  orbitControl()
  rotateX(radians(30))
  rotateY(radians(45))

  ambientLight(10)
  let lightColor = [200, 200, 200]

  // directional lights from cardinal points (8 horizontal + 1 top)
  directionalLight(...lightColor, 0, -1, 1)
  directionalLight(...lightColor, 1, -1, 1)
  directionalLight(...lightColor, 1, -1, 0)
  directionalLight(...lightColor, 1, -1, -1)
  directionalLight(...lightColor, 0, -1, -1)
  directionalLight(...lightColor, -1, -1, -1)
  directionalLight(...lightColor, -1, -1, 0)
  directionalLight(...lightColor, -1, -1, 1)
  directionalLight(...lightColor, 0, -1, 0)

  specularColor(20, 20, 20)

  translate(0, height / 4, 0)
  updateLayers()
  drawLayers()

  if (currentLayer <= maxLayers && layers.length === 0) {
    spawnLayer()
  }

  colorMode(HSB)
  let hue = map(sin(frameCount * 0.0015), -1, 1, 0, 360)
  let colors = color(hue, 100, 40)._array
  colorMode(RGB)

  let blockSize = 1.0
  ditherShader.setUniform("uColor", colors)
  ditherShader.setUniform("resolution", [width, height])
  ditherShader.setUniform("blockSize", blockSize)
  filter(ditherShader)
}

function createSquigglyShader() {
  squigglyShader = baseStrokeShader().modify({
    uniforms: {
      'float time': () => millis()
    },
    declarations: 'vec3 myPosition;',
    'vec3 getWorldPosition': `(vec3 pos) {
      myPosition = pos;
      vec2 posXZ = vec2(pos.x, pos.z);
      float distFromCenterXZ = length(posXZ);
      vec2 dirFromCenterXZ = distFromCenterXZ > 0.001 ? normalize(posXZ) : vec2(0.0);
      vec2 particleSeed = posXZ * 0.15 + vec2(time * 0.0002);
      float particleRandom = random(particleSeed * 8.0);
      float particleChance = smoothstep(0.75, 0.95, particleRandom) * smoothstep(40.0, 120.0, distFromCenterXZ);
      float particleOffset = particleChance * 100.0;
      vec3 offset = vec3(dirFromCenterXZ.x * particleOffset, 0.0, dirFromCenterXZ.y * particleOffset);
      return pos + offset;
    }`,
    'float getStrokeWeight': `(float w) {
      float scale = 1.0 + 0.8 * sin(10.0 * sin(
        floor(time/200.0) +
        myPosition.x*0.10 +
        myPosition.y*0.10
      ));
      return w * scale;
    }`,
    'float random': `(vec2 p) {
      vec3 p3  = fract(vec3(p.xyx) * .1031);
      p3 += dot(p3, p3.yzx + 33.33);
      return fract((p3.x + p3.y) * p3.z);
    }`,
    'float noise': `(vec2 p) {
      vec2 i = floor(p);
      vec2 f = fract(p);
      f = f * f * (3.0 - 2.0 * f);
      float n = i.x + i.y * 57.0;
      return mix(mix(random(vec2(n)), random(vec2(n + 1.0)), f.x),
                 mix(random(vec2(n + 57.0)), random(vec2(n + 58.0)), f.x), f.y);
    }`,
    'Inputs getPixelInputs': `(Inputs inputs) {
      // inputs.position is vec2 (screen space), use myPosition for world space
      // Calculate direction from pyramid center (0,0,0) to world position
      vec3 pos = myPosition;
      float distFromCenter = length(pos);
      vec3 dirFromCenter = distFromCenter > 0.001 ? normalize(pos) : vec3(0.0);
      vec2 particleCoord = pos.xy * 0.25 + dirFromCenter.xy * distFromCenter * 0.01 + vec2(time * 0.0003);
      float particleNoise = noise(particleCoord * 15.0);
      float particleDensity = smoothstep(20.0, 120.0, distFromCenter);
      float outwardBias = max(0.0, dot(dirFromCenter, dirFromCenter)) * 0.4;
      float particleValue = particleNoise * (particleDensity + outwardBias);
      float particleThreshold = 0.7;
      if (particleValue > particleThreshold) {
        inputs.color.rgb = mix(inputs.color.rgb, vec3(0.0), 0.95);
        inputs.color.rgb *= 0.15;
      } else if (particleValue > particleThreshold - 0.12) {
        inputs.color.rgb *= 0.4;
      } else if (particleValue > particleThreshold - 0.2) {
        inputs.color.rgb *= 0.7;
      }
      vec2 screenPos = inputs.position;
      float dither = random(screenPos * 0.15 + time * 0.0001);
      inputs.color.rgb *= mix(0.96, 1.04, dither);
      return inputs;
    }`
  })
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight)
  ortho(-width / 2, width / 2, -height / 2, height / 2, -2000, 2000)
  maxLayers = calculateMaxLayers()
  calculateSpawnPosition()
}

function spawnLayer() {
  let size = currentLayer * unitSize
  let y = spawnStartY
  let divisions = generateDivisions(size)
  let bottomColor = random(palette)
  let noiseInput = currentLayer * 0.01
  let baseRotation = map(noise(noiseInput), 0, 1, 0, TWO_PI)

  layers.push({
    size: size,
    y: y,
    layerNum: currentLayer,
    divisions: divisions,
    bottomColor: bottomColor,
    baseRotationY: baseRotation,
  })

  currentLayer += 1
}

function generateDivisions(layerSize) {
  let baseNumDivisions = 2 + floor(layerSize / (2 * unitSize))
  let faceDivisions = []

  for (let face = 0; face < 4; face++) {
    let numDivisions = max(2, baseNumDivisions + floor(random(-4, 4)))
    var divisions = []
    let segmentWeights = []
    let totalWeight = 0
    let targetSize = 1.0 / numDivisions

    for (let i = 0; i < numDivisions; i++) {
      let weight = random(targetSize * 0.5, targetSize * 1.5)
      segmentWeights.push(weight)
      totalWeight += weight
    }

    let cumulative = 0
    let normalizedSizes = segmentWeights.map(w => {
      let normalized = w / totalWeight
      let start = cumulative
      cumulative += normalized
      return { start: start, size: normalized }
    })

    var colors = []
    for (let i = 0; i < numDivisions; i++) {
      let colorIndex
      do {
        colorIndex = floor(random(palette.length))
      } while (i > 0 && colorIndex === colors[i - 1])

      colors.push(colorIndex)
    }

    for (let i = 0; i < numDivisions; i++) {
      divisions.push({
        start: normalizedSizes[i].start,
        end: normalizedSizes[i].start + normalizedSizes[i].size,
        color: palette[colors[i]]
      })
    }

    faceDivisions.push(divisions)
  }

  return faceDivisions
}

function updateLayers() {
  for (let i = layers.length - 1; i >= 0; i--) {
    let layer = layers[i]
    let targetY = 0

    if (i > 0) {
      let prevLayer = layers[i - 1]
      targetY = prevLayer.y - layerHeight * unitSize
    } else {
      targetY = height / 4
    }

    if (layer.y < targetY) {
      layer.y += fallSpeed
      if (layer.y >= targetY) {
        layer.y = targetY
      }
    } else {
      if (currentLayer <= maxLayers && i === layers.length - 1) {
        spawnLayer()
      }
    }
  }
}

function drawLayers() {
  let globalRotation = frameCount * globalRotationSpeed
  squigglyShader.setUniform('u_time', millis())
  shader(squigglyShader)

  for (let i = layers.length - 1; i >= 0; i--) {
    push()
    var layer = layers[i]
    translate(0, layer.y, 0)
    let layerVariation = noise(layer.layerNum * 0.05, frameCount * 0.01) * 0.1
    let totalRotation = layer.baseRotationY + globalRotation + layerVariation
    rotateY(totalRotation)
    drawLayer(layer)
    pop()
  }
}

function drawLayer(layer) {
  var size = layer.size
  let h = layerHeight * unitSize
  let halfSize = size / 2
  let halfHeight = h / 2

  colorMode(RGB)

  let faces = [
    { name: 'front', rot: 0 },
    { name: 'right', rot: HALF_PI },
    { name: 'back',  rot: PI },
    { name: 'left',  rot: -HALF_PI }
  ]

  for (let i = 0; i < faces.length; i++) {
    push()
    rotateY(faces[i].rot)
    translate(0, 0, halfSize)

    var divisions = layer.divisions[i]
    for (let div of divisions) {
      let c = color(div.color)
      c.setAlpha(40)
      specularMaterial(c)
      noStroke()

      let segmentStart = -halfSize + div.start * size
      let segmentEnd   = -halfSize + div.end * size

      beginShape()
      vertex(segmentStart, -halfHeight, 0)
      vertex(segmentEnd,   -halfHeight, 0)
      vertex(segmentEnd,    halfHeight, 0)
      vertex(segmentStart,  halfHeight, 0)
      endShape(CLOSE)
    }
    pop()
  }
  push()
  noStroke()
  translate(0, -halfHeight, 0)
  rotateX(-PI / 2)
  fill(layer.bottomColor)
  rect(-halfSize, -halfSize, size, size)
  pop()

  strokeWeight(random(4, 8))
  stroke(layer.bottomColor + '80')
  noFill()
  box(size, h, size)
}

